/// Binary search for `cp`'s full case mapping; null means identity.
pub fn lookup(table: []const Entry, cp: u21) ?[]const u21 {
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = table[mid];
        if (e.cp == cp) return e.map;
        if (e.cp < cp) lo = mid + 1 else hi = mid;
    }
    return null;
}
